package app.honorable.editor
import org.junit.Assert.*
import org.junit.Test
class PhotoPresetsTest {
 @Test fun codecRoundTripKeepsAdjustmentsAndUnicodeName(){val c=PhotoPresetCatalog().add(NamedPhotoPreset("Warm café",PhotoAdjustmentPreset(exposure=.5f,warmth=.4f)));assertEquals(c,PhotoPresetCodec.decode(PhotoPresetCodec.encode(c)))}
 @Test fun applicationPreservesFramingLocalLightAndText(){val target=PhotoEdit(rotation=90,crop=.8f,radialLight=PhotoRadialLight(exposure=.5f),finish=PhotoFinish(mirrorX=true,caption=PhotoCaption("Hello")));val applied=PhotoAdjustmentPreset(exposure=1f,warmth=.4f).applyTo(target);assertEquals(target.rotation,applied.rotation);assertEquals(target.crop,applied.crop);assertEquals(target.radialLight,applied.radialLight);assertEquals(target.finish.caption,applied.finish.caption);assertTrue(applied.finish.mirrorX);assertEquals(1f,applied.exposure)}
 @Test fun duplicateAndOverflowDoNotMutateShelf(){val c=PhotoPresetCatalog((1..20).map{NamedPhotoPreset("Look $it",PhotoAdjustmentPreset())});assertTrue(runCatching{c.add(NamedPhotoPreset("LOOK 1",PhotoAdjustmentPreset()))}.isFailure);assertTrue(runCatching{c.add(NamedPhotoPreset("Extra",PhotoAdjustmentPreset()))}.isFailure);assertEquals(20,c.entries.size)}
 @Test fun malformedAndFuturePayloadsFailClosed(){val bytes=PhotoPresetCodec.encode(PhotoPresetCatalog());assertTrue(runCatching{PhotoPresetCodec.decode(bytes+byteArrayOf(1))}.isFailure);bytes[7]=4;assertTrue(runCatching{PhotoPresetCodec.decode(bytes)}.isFailure);assertTrue(runCatching{PhotoPresetCodec.decode(ByteArray(9000))}.isFailure)}
 @Test fun invalidNamesAndNonFiniteValuesAreRejected(){listOf("", "  hi", "line\nnext", "x".repeat(41)).forEach{assertTrue(runCatching{NamedPhotoPreset(it,PhotoAdjustmentPreset())}.isFailure)};assertTrue(runCatching{PhotoAdjustmentPreset(exposure=Float.NaN)}.isFailure)}
 @Test fun deletionIsCaseInsensitiveAndImmutable(){val old=PhotoPresetCatalog().add(NamedPhotoPreset("Warm",PhotoAdjustmentPreset()));assertTrue(old.remove("WARM").entries.isEmpty());assertEquals(1,old.entries.size)}
 @Test fun scopesSeparateGuestsAccountsAndServers(){val a=PhotoPresetNamespace.account("alice","https://one.example");assertTrue(PhotoPresetNamespace.valid(a));assertNotEquals(a,PhotoPresetNamespace.GUEST);assertNotEquals(a,PhotoPresetNamespace.account("bob","https://one.example"));assertNotEquals(a,PhotoPresetNamespace.account("alice","https://two.example"));assertFalse(PhotoPresetNamespace.valid("../guest"))}
}
